{
  "format": "canaryfield-seeds/10",
  "seeds": [
    {
      "id": "seed-00",
      "name": "stale version string",
      "defect_class": "stale metadata",
      "description": "Replaces a version literal with the stale string 9.9.9"
    },
    {
      "id": "seed-01",
      "name": "dropped return value",
      "defect_class": "missing result",
      "description": "Drops the value from a return so the caller gets nothing"
    },
    {
      "id": "seed-02",
      "name": "inverted comparison",
      "defect_class": "wrong predicate",
      "description": "Flips a comparison operator to its opposite"
    },
    {
      "id": "seed-03",
      "name": "off by one constant",
      "defect_class": "boundary error",
      "description": "Adds one to an integer constant in a return or comparison"
    },
    {
      "id": "seed-04",
      "name": "swallowed exception",
      "defect_class": "hidden failure",
      "description": "Replaces an exception handler body with a silent pass"
    },
    {
      "id": "seed-05",
      "name": "inverted boolean literal",
      "defect_class": "wrong flag",
      "description": "Flips a boolean literal to its opposite"
    },
    {
      "id": "seed-06",
      "name": "swapped arithmetic operator",
      "defect_class": "wrong computation",
      "description": "Swaps an arithmetic operator for a different one"
    },
    {
      "id": "seed-07",
      "name": "dropped call argument",
      "defect_class": "missing input",
      "description": "Drops the last argument from a call that takes at least two"
    },
    {
      "id": "seed-08",
      "name": "negated condition",
      "defect_class": "wrong branch",
      "description": "Wraps an if condition in a negation"
    },
    {
      "id": "seed-09",
      "name": "removed collection element",
      "defect_class": "missing data",
      "description": "Removes the first element from a list or dictionary literal"
    },
    {
      "id": "seed-10",
      "name": "range bound shifted by one",
      "defect_class": "boundary error",
      "description": "Raises the last bound of a range call by one"
    },
    {
      "id": "seed-11",
      "name": "wrong variable returned",
      "defect_class": "wrong result",
      "description": "Returns the next parameter instead of the one the code named"
    },
    {
      "id": "seed-12",
      "name": "swapped operand order",
      "defect_class": "wrong computation",
      "description": "Swaps the operands of a subtraction, division, floor division, or modulo, where the order of the operands decides the result"
    },
    {
      "id": "seed-13",
      "name": "dropped else branch",
      "defect_class": "missing fallback",
      "description": "Drops the else branch of a conditional so the fallback path never runs"
    },
    {
      "id": "seed-14",
      "name": "swapped boolean operator",
      "defect_class": "wrong predicate",
      "description": "Swaps a boolean and for an or, or an or for an and, in a compound condition"
    },
    {
      "id": "seed-15",
      "name": "dropped await",
      "defect_class": "missing wait",
      "description": "Removes an await so the caller holds a coroutine instead of the awaited result"
    },
    {
      "id": "seed-16",
      "name": "widened exception handler",
      "defect_class": "hidden failure",
      "description": "Widens an exception handler so it catches the broad base error type"
    },
    {
      "id": "seed-17",
      "name": "swapped dictionary entry",
      "defect_class": "wrong data",
      "description": "Swaps the key and the value of a dictionary entry so the mapping answers backwards"
    },
    {
      "id": "seed-18",
      "name": "inverted truth test",
      "defect_class": "wrong branch",
      "description": "Toggles the negation on a condition test so its sense reads backwards on the shapes no other seed plants"
    },
    {
      "id": "seed-19",
      "name": "reassigned loop variable",
      "defect_class": "wrong variable",
      "description": "Points a for loop at a different name already bound in the same scope so the loop writes into the wrong variable"
    },
    {
      "id": "seed-20",
      "name": "swapped call argument order",
      "defect_class": "wrong input",
      "description": "Swaps the first two positional arguments of a call so each value reaches the wrong parameter"
    },
    {
      "id": "seed-21",
      "name": "altered string literal",
      "defect_class": "wrong text",
      "description": "Changes the first character of a string literal so the text the code compares or returns is no longer the text it wrote"
    },
    {
      "id": "seed-22",
      "name": "dropped numeric negation",
      "defect_class": "wrong sign",
      "description": "Removes a unary minus so a value carries the opposite sign from the one the code wrote"
    },
    {
      "id": "seed-23",
      "name": "swapped loop control",
      "defect_class": "wrong flow",
      "description": "Turns a break inside a loop into a continue so the loop runs on instead of ending"
    },
    {
      "id": "seed-24",
      "name": "swapped augmented assignment operator",
      "defect_class": "wrong computation",
      "description": "Swaps the operator of an augmented assignment so the value it accumulates moves the wrong way"
    },
    {
      "id": "seed-25",
      "name": "identity test replaced by equality",
      "defect_class": "wrong predicate",
      "description": "Replaces an identity comparison with an equality comparison so the test asks sameness of value instead of sameness of object"
    },
    {
      "id": "seed-26",
      "name": "subscript index shifted by one",
      "defect_class": "boundary error",
      "description": "Raises the constant index of a subscript by one so the code reads the element beside the one it named"
    },
    {
      "id": "seed-27",
      "name": "swapped keyword argument values",
      "defect_class": "wrong input",
      "description": "Swaps the values of the first two keyword arguments of a call so each value binds to the wrong parameter"
    },
    {
      "id": "seed-28",
      "name": "swapped raised error",
      "defect_class": "wrong error",
      "description": "Swaps the exception type a raise throws for the first other exception type the module names so the error a caller handles is never the one that arrives"
    },
    {
      "id": "seed-29",
      "name": "slice stop shifted by one",
      "defect_class": "boundary error",
      "description": "Raises the stop of a slice by one so the code takes one element more than the slice it wrote"
    },
    {
      "id": "seed-30",
      "name": "shifted numeric default",
      "defect_class": "wrong default",
      "description": "Raises a numeric argument default by one so a call that leaves the argument out runs with a value the code never wrote"
    },
    {
      "id": "seed-31",
      "name": "swapped sibling attribute",
      "defect_class": "wrong attribute",
      "description": "Reads the second attribute a scope loads off one object in place of the first so the value comes from a different part of the object than the code named"
    },
    {
      "id": "seed-32",
      "name": "narrowed exception handler",
      "defect_class": "exposed failure",
      "description": "Narrows an exception handler that names the broad base error type to the first specific error type its try body raises so the other failures the handler was written to recover from escape past it"
    },
    {
      "id": "seed-33",
      "name": "swapped parameter defaults",
      "defect_class": "wrong default",
      "description": "Exchanges the first two argument defaults of a definition so each parameter falls back to the value the code wrote for the other"
    },
    {
      "id": "seed-34",
      "name": "dropped finally body",
      "defect_class": "missing cleanup",
      "description": "Drops the finally block of a try statement so the cleanup the code wrote to run on every path never runs"
    },
    {
      "id": "seed-35",
      "name": "dropped decorator",
      "defect_class": "missing wrapper",
      "description": "Removes the first decorator from a definition so the behaviour the decorator added never runs"
    },
    {
      "id": "seed-36",
      "name": "dropped exception handler",
      "defect_class": "missing recovery",
      "description": "Removes the first exception handler of a try statement so the failure it was written to recover from reaches a later handler instead, or escapes to the caller where no handler stands after it"
    },
    {
      "id": "seed-37",
      "name": "dropped yield",
      "defect_class": "missing production",
      "description": "Replaces each yield with the value it yields so the function runs as an ordinary function and produces none of the items it was written to generate"
    },
    {
      "id": "seed-38",
      "name": "dropped condition term",
      "defect_class": "wrong predicate",
      "description": "Drops the last term of a compound condition so the cases that term admitted or rejected are decided by the terms that stay"
    },
    {
      "id": "seed-39",
      "name": "dropped base class",
      "defect_class": "missing inheritance",
      "description": "Removes the first base class of a class definition so the behaviour the class inherited from that base is not there"
    },
    {
      "id": "seed-40",
      "name": "shifted slice start",
      "defect_class": "boundary error",
      "description": "Raises the start of a slice by one so the code takes its elements from one position later than the slice it wrote"
    },
    {
      "id": "seed-41",
      "name": "reversed loop control",
      "defect_class": "wrong flow",
      "description": "Turns a continue inside a loop into a break so the loop ends at the first item it was written to skip and every later item goes unprocessed"
    },
    {
      "id": "seed-42",
      "name": "dropped scope declaration",
      "defect_class": "wrong scope",
      "description": "Removes a global or nonlocal declaration so a plain assignment meant for the module or the enclosing scope lands in a local and is lost silently, and an augmented assignment reads that local first and raises instead"
    },
    {
      "id": "seed-43",
      "name": "swapped assignment values",
      "defect_class": "wrong data",
      "description": "Exchanges the first two elements of the tuple an assignment binds so each name takes the value the code wrote for the other"
    },
    {
      "id": "seed-44",
      "name": "dropped loop else clause",
      "defect_class": "missing fallback",
      "description": "Drops the else clause of a loop so the code written to run when the loop finishes without a break never runs"
    },
    {
      "id": "seed-45",
      "name": "dropped keyword argument",
      "defect_class": "missing input",
      "description": "Drops the first keyword argument of a call so the callee never receives the value the caller named for that parameter"
    },
    {
      "id": "seed-46",
      "name": "flipped range step sign",
      "defect_class": "wrong direction",
      "description": "Negates the step of a range call carrying three arguments so the sequence travels in the opposite direction from the one the code wrote"
    },
    {
      "id": "seed-47",
      "name": "dropped logical negation",
      "defect_class": "wrong flag",
      "description": "Removes a logical not standing outside a condition test so the expression it negated carries the opposite truth from the one the code wrote"
    }
  ]
}

